+fn slot_with_tilt(tilt: Option<Tilt>) -> OpParams {
+    let above = |offset_in: f64| Height::of(HeightReference::TopOfStock, offset_in * IN);
+    OpParams::Slot {
+        a: Point2::new(-0.75 * IN, 0.0),
+        b: Point2::new(-0.25 * IN, 0.0),
+        width: 0.25 * IN,
+        stock_to_leave: 0.0,
+        clearance_z: above(0.5),
