+        top_z: above(0.0),
+        bottom_z: above(-0.015),
+        stepdown: 0.015 * IN,
+        stepover: 3.0,
+        feed: 15.0 * IN,
+        plunge_feed: 4.0 * IN,
+        climb: true,
+        entry: Entry3D::Plunge,
+        helix_radius: 1.0,
+        links: camcraft_app::links::Links::PLANAR,
+        tilt,
+        extend_start: 0.0,
+        extend_end: 0.0,
